From 3df3fa396c7b338928f77344edd8c4dcda957671 Mon Sep 17 00:00:00 2001
From: Steve Loughran <stevel@apache.org>
Date: Thu, 24 Nov 2016 17:44:14 +0000
Subject: [PATCH] HADOOP-13833
 TestSymlinkHdfsFileSystem#testCreateLinkUsingPartQualPath2 fails after
 HADOOP-13605. Contributed by Brahma Reddy Battula.


diff --git a/hadoop-common-project/hadoop-common/src/test/java/org/apache/hadoop/fs/SymlinkBaseTest.java b/hadoop-common-project/hadoop-common/src/test/java/org/apache/hadoop/fs/SymlinkBaseTest.java
index a5808e6c80f..90e8c90c7ba 100644
--- a/hadoop-common-project/hadoop-common/src/test/java/org/apache/hadoop/fs/SymlinkBaseTest.java
+++ b/hadoop-common-project/hadoop-common/src/test/java/org/apache/hadoop/fs/SymlinkBaseTest.java
@@ -571,7 +571,8 @@ public void testCreateLinkUsingPartQualPath2() throws IOException {
         GenericTestUtils.assertExceptionContains(
             AbstractFileSystem.NO_ABSTRACT_FS_ERROR, e);
       } else if (wrapper instanceof FileSystemTestWrapper) {
-        assertEquals("No FileSystem for scheme: null", e.getMessage());
+        assertEquals("No FileSystem for scheme " + "\"" + "null" + "\"",
+            e.getMessage());
       }
     }
   }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a change in the behavior of the file system handling in HADOOP-13605, which resulted in the exception message being altered. The test case was not updated to reflect this change, leading to a mismatch between the expected and actual exception messages when a null scheme was encountered.

        Commit message:
        HADOOP-13833
 TestSymlinkHdfsFileSystem#testCreateLinkUsingPartQualPath2 fails after
 HADOOP-13605. Contributed by Brahma Reddy Battula.  

        Patch:

   @Test(timeout=10000)
   /** Same as above but vice versa (authority but no scheme) */
   public void testCreateLinkUsingPartQualPath2() throws IOException {
     Path link         = new Path(testBaseDir1(), "linkToFile");
     Path fileWoScheme = new Path("//"+testURI().getAuthority()+
                                  testBaseDir1()+"/file");
     if ("file".equals(getScheme())) {
       return;
     }
     wrapper.createSymlink(fileWoScheme, link, false);
     assertEquals(fileWoScheme, wrapper.getLinkTarget(link));
     assertEquals(fileWoScheme.toString(),
       wrapper.getFileLinkStatus(link).getSymlink().toString());
     try {
       readFile(link);
       fail("Accessed a file with w/o scheme");
     } catch (IOException e) {
       // Expected
       if (wrapper instanceof FileContextTestWrapper) {
         GenericTestUtils.assertExceptionContains(
             AbstractFileSystem.NO_ABSTRACT_FS_ERROR, e);
       } else if (wrapper instanceof FileSystemTestWrapper) {
-        assertEquals("No FileSystem for scheme: null", e.getMessage());
+        assertEquals("No FileSystem for scheme " + "\"" + "null" + "\"",
+            e.getMessage());
       }
     }
   }



